package bo.colbert.cobros;

import android.app.*;
import android.os.*;
import android.content.*;
import android.graphics.*;
import android.widget.*;
import android.view.WindowManager;
import bo.colbert.licensing.*;
import org.json.*;
import java.io.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.concurrent.*;

public final class BillingActivity extends Activity {
 private LicenseUi ui;private BillingRuntime runtime;private boolean authorized,busy,authPending;private final ExecutorService worker=Executors.newSingleThreadExecutor();private long background;
 private String current="",qr="",draftPrice="",draftNote="",draftInterval="month",exportClient="";private char[] backupPassword;private TextView network;
 private final Handler handler=new Handler(Looper.getMainLooper());private final Runnable update=new Runnable(){public void run(){if(network!=null)network.setText(BillingService.status);handler.postDelayed(this,3000);}};
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);ui=new LicenseUi(this);locked();}
 void locked(){ui.screen("Tu centro de cobros","Administración privada · solo en tu teléfono");ui.banner("Acceso protegido","Desbloquea con la seguridad del teléfono para administrar tus clientes.",LicenseUi.INK);ui.button("Desbloquear administración",LicenseUi.BLUE,this::authenticate);}
 void authenticate(){if(authPending)return;KeyguardManager k=getSystemService(KeyguardManager.class);if(!k.isDeviceSecure()){ui.error("Configura primero un PIN, patrón o contraseña de bloqueo en los ajustes de Android. Así protegemos tus cobros.");startActivity(new Intent(android.provider.Settings.ACTION_SECURITY_SETTINGS));return;}Intent intent=k.createConfirmDeviceCredentialIntent("Colbert · Cobros","Confirma tu identidad para administrar permisos y pagos.");if(intent!=null){authPending=true;startActivityForResult(intent,700);}}
 @Override protected void onResume(){super.onResume();if(authorized&&background>0&&SystemClock.elapsedRealtime()-background>60000){authorized=false;locked();}handler.removeCallbacks(update);handler.post(update);}
 @Override protected void onPause(){background=SystemClock.elapsedRealtime();handler.removeCallbacks(update);super.onPause();}
 @Override protected void onDestroy(){handler.removeCallbacks(update);worker.shutdown();if(backupPassword!=null)Arrays.fill(backupPassword,'\0');super.onDestroy();}
 interface Job{void run()throws Exception;}
 void action(Job job,Runnable after){if(!authorized||busy||isFinishing()||isDestroyed())return;busy=true;worker.execute(()->{String problem=null;try{job.run();}catch(Exception e){problem=e.getMessage()==null?"No se pudo completar la operación.":e.getMessage();}String error=problem;runOnUiThread(()->{busy=false;if(isFinishing()||isDestroyed())return;if(error!=null)ui.error(error);else if(authorized)after.run();});});}
 void open(){action(()->runtime=BillingRuntime.get(this),()->{if(runtime.config==null){ui.screen("Preparar servidor","Este teléfono será tu servidor privado de cobros.");ui.button("Activar configuración incluida",LicenseUi.BLUE,()->action(runtime::setup,this::home));ui.button("Restaurar respaldo cifrado",LicenseUi.INK,this::restorePrompt);}else home();});}
 void home(){try{network=null;ui.screen("Centro de cobros","Jesús Colbert · clientes, permisos y pagos");JSONArray pending=runtime.db.pending();ui.banner(pending.length()+" solicitudes pendientes","Revisa el pago en tu banco antes de aprobar un comprobante.",LicenseUi.INK);network=ui.text(BillingService.status,16,LicenseUi.MUTED);ui.text(runtime.config.getString("url"),12,LicenseUi.MUTED);
  ui.button(BillingService.active?"Detener servidor":"Encender servidor",BillingService.active?LicenseUi.RED:LicenseUi.GREEN,()->{if(BillingService.active){confirm("Detener servidor","No llegarán comprobantes ni nuevos permisos hasta que lo enciendas. Los permisos ya validados conservan su vencimiento.",()->{stopService(new Intent(this,BillingService.class));home();});}else{if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},701);startForegroundService(new Intent(this,BillingService.class));ui.error("Servidor iniciado. Mantén este teléfono conectado a internet; Android puede detenerlo por batería.");}});
  ui.button("Revisar comprobantes ("+pending.length()+")",LicenseUi.BLUE,this::receipts);ui.button("Agregar cliente y aplicación",LicenseUi.BLUE,this::newContract);
  ui.text("Tus clientes",24,LicenseUi.INK);JSONArray clients=runtime.db.contracts();for(int i=0;i<clients.length();i++){JSONObject c=clients.getJSONObject(i);String id=c.getString("id");String mode=c.getString("mode");String label=mode.equals("free")?"Sin cobro activado":mode.equals("suspended")?"Suspendido":c.getLong("paidUntil")>System.currentTimeMillis()?"Pagado hasta "+LicenseUi.when(c.getLong("paidUntil")):"Pendiente de pago";ui.button(c.getString("customer")+"\n"+c.getString("productName")+" · "+label,LicenseUi.INK,()->contract(id));}
  ui.button("Guardar respaldo cifrado",LicenseUi.BLUE,this::backupPrompt);ui.text("Guarda un respaldo fuera de este teléfono después de cambios y aprobaciones. Incluye clientes, comprobantes y la identidad del servidor. La contraseña no se recupera.",13,LicenseUi.MUTED);ui.button("Bloquear administración",LicenseUi.INK,()->{authorized=false;locked();});
 }catch(Exception e){ui.error("No se pudo cargar la administración.");}}
 void contract(String id){try{current=id;JSONObject c=runtime.db.contract(id);network=null;ui.screen(c.getString("customer"),c.getString("productName")+" · todos sus equipos");ui.banner(c.getString("mode").equals("free")?"Sin cobro activado":c.getString("mode").equals("suspended")?"Suspendido":c.getLong("paidUntil")>System.currentTimeMillis()?"Acceso pagado":"Pago pendiente",LicenseUi.money(c)+(c.getString("interval").equals("day")?" / día":" / mes"),LicenseUi.INK);ui.text("Pagado hasta: "+LicenseUi.when(c.getLong("paidUntil")),15,LicenseUi.MUTED);
  ui.button("Editar precio, frecuencia y QR de pago",LicenseUi.BLUE,()->{draftPrice=String.format(Locale.ROOT,"%.2f",c.optLong("amountMinor")/100.0);draftNote=c.optString("note");draftInterval=c.optString("interval");qr=c.optString("paymentQr");plan();});
  ui.button("Solicitar pago y bloquear uso",LicenseUi.RED,()->confirm("Solicitar pago","Se exigirá el pago al recibir la actualización de permiso. Un equipo sin conexión podría seguir usando su permiso anterior hasta 24 horas, sin superar su vencimiento. ¿Aplicar a todos los equipos de este cliente y aplicación?",()->action(()->runtime.db.charge(id,System.currentTimeMillis()),()->contract(id))));
  if(c.getString("mode").equals("billing")&&c.getLong("paidUntil")<=System.currentTimeMillis())ui.button("Reemplazar cobro con nueva tarifa / QR",LicenseUi.BLUE,()->confirm("Reemplazar cobro pendiente","El cobro anterior será cancelado y se aplicarán el precio y QR guardados. Revisa antes los comprobantes recibidos.",()->action(()->runtime.db.revise(id,System.currentTimeMillis()),()->contract(id))));
  ui.button("Habilitar sin cobro",LicenseUi.GREEN,()->confirm("Habilitar sin cobro","Se cancelará el cobro pendiente. Todos los equipos de este cliente podrán usar esta aplicación al validar su permiso.",()->action(()->runtime.db.free(id,System.currentTimeMillis()),()->contract(id))));
  ui.button("Suspender acceso manualmente",LicenseUi.RED,()->confirm("Suspender acceso","Los equipos conectados recibirán la suspensión al validar. Los desconectados conservan como máximo el permiso de 24 horas.",()->action(()->runtime.db.suspend(id,System.currentTimeMillis()),()->contract(id))));
  ui.button("Exportar conexión para esta aplicación",LicenseUi.BLUE,()->{exportClient=id;Intent save=new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/json").putExtra(Intent.EXTRA_TITLE,"licencia-"+id+".json").addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(save,705);});ui.text("Este archivo es para integrar o preparar la aplicación de ese cliente. No lo publiques. SOBOCE ya tendrá su conexión incluida en la APK.",13,LicenseUi.MUTED);ui.button("Volver",LicenseUi.INK,this::home);
 }catch(Exception e){ui.error("No se pudo cargar el cliente.");}}
 void plan(){ui.screen("Configurar cobro","El precio nuevo se aplica a los próximos cobros. Los ya emitidos conservan su importe y QR.");EditText price=ui.field("Precio en bolivianos (Bs)",draftPrice);price.setInputType(8194);Spinner period=new Spinner(this);period.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Mensual","Diario"}));period.setSelection(draftInterval.equals("day")?1:0);ui.page.addView(period);EditText note=ui.field("Instrucciones de pago / cuenta / titular",draftNote);note.setSingleLine(false);if(!qr.isEmpty())picture(qr);
  Runnable keep=()->{draftPrice=price.getText().toString();draftNote=note.getText().toString();draftInterval=period.getSelectedItemPosition()==1?"day":"month";};ui.button("Seleccionar o cambiar QR de pago",LicenseUi.BLUE,()->{keep.run();startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("image/*").addCategory(Intent.CATEGORY_OPENABLE),702);});ui.button("Quitar imagen QR",LicenseUi.INK,()->{keep.run();qr="";plan();});ui.button("Guardar configuración",LicenseUi.GREEN,()->{keep.run();action(()->{long minor=new BigDecimal(draftPrice.replace(',','.')).movePointRight(2).longValueExact();runtime.db.plan(current,minor,draftInterval,draftNote,qr,System.currentTimeMillis());},()->contract(current));});ui.button("Volver",LicenseUi.INK,()->contract(current));}
 void newContract(){ui.screen("Nuevo cliente y aplicación","Cada combinación tiene su precio y permiso independiente.");EditText name=ui.field("Cliente o empresa",""),product=ui.field("Código de aplicación (sin espacios)",""),display=ui.field("Nombre de la aplicación","");ui.button("Crear sin cobro activado",LicenseUi.GREEN,()->action(()->runtime.add(name.getText().toString().trim(),product.getText().toString().trim(),display.getText().toString().trim()),this::home));ui.button("Volver",LicenseUi.INK,this::home);}
 void receipts(){try{ui.screen("Comprobantes","Verifica el ingreso en tu banco. La imagen no confirma un pago por sí sola.");JSONArray rows=runtime.db.pending();if(rows.length()==0)ui.text("No hay solicitudes pendientes.",19,LicenseUi.MUTED);for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i),c=runtime.db.contract(r.getString("contractId")),inv=runtime.db.get("invoice",r.getString("invoiceId"));ui.button(c.getString("customer")+" · "+c.getString("productName")+"\n"+LicenseUi.money(inv)+" · "+LicenseUi.when(r.getLong("created")),LicenseUi.BLUE,()->receipt(r.optString("id")));}ui.button("Actualizar",LicenseUi.BLUE,this::receipts);ui.button("Volver",LicenseUi.INK,this::home);}catch(Exception e){ui.error("No se pudieron cargar los comprobantes.");}}
 void receipt(String id){try{JSONObject r=runtime.db.get("receipt",id),c=runtime.db.contract(r.getString("contractId")),inv=runtime.db.get("invoice",r.getString("invoiceId"));ui.screen("Revisar pago",c.getString("customer")+" · "+c.getString("productName"));ui.banner(LicenseUi.money(inv),inv.getString("interval").equals("day")?"Habilitará un día desde la aprobación":"Habilitará un mes desde la aprobación",LicenseUi.INK);picture(r.getString("image"));ui.text(r.optString("note"),16,LicenseUi.INK);ui.text("Compara importe, beneficiario, fecha y referencia con el movimiento en tu banco.",15,LicenseUi.MUTED);EditText review=ui.field("Observación para el cliente (opcional)","");ui.button("Pago verificado · aprobar y habilitar",LicenseUi.GREEN,()->confirm("Confirmar pago verificado","Se habilitarán todos los equipos de este cliente para esta aplicación. Aprobar nuevamente no agregará otro período.",()->action(()->runtime.db.review(id,true,review.getText().toString(),System.currentTimeMillis()),this::receipts)));ui.button("Rechazar comprobante",LicenseUi.RED,()->action(()->runtime.db.review(id,false,review.getText().toString(),System.currentTimeMillis()),this::receipts));ui.button("Volver",LicenseUi.INK,this::receipts);}catch(Exception e){ui.error("No se pudo abrir el comprobante.");}}
 void picture(String data){try{byte[] b=Base64.getDecoder().decode(data);Bitmap image=BitmapFactory.decodeByteArray(b,0,b.length);ImageView v=new ImageView(this);v.setImageBitmap(image);v.setAdjustViewBounds(true);ui.page.addView(v,new LinearLayout.LayoutParams(-1,-2));}catch(Exception e){ui.text("Imagen no disponible",14,LicenseUi.RED);}}
 void confirm(String title,String text,Runnable yes){if(!authorized||busy)return;new AlertDialog.Builder(this).setTitle(title).setMessage(text).setNegativeButton("Cancelar",null).setPositiveButton("Confirmar",(d,w)->{if(authorized)yes.run();}).show();}
 void password(String title,Runnable next){EditText input=new EditText(this);input.setInputType(129);input.setHint("Mínimo 10 caracteres");new AlertDialog.Builder(this).setTitle(title).setView(input).setNegativeButton("Cancelar",null).setPositiveButton("Continuar",(d,w)->{if(!authorized)return;backupPassword=input.getText().toString().toCharArray();if(backupPassword.length<10){ui.error("La contraseña debe tener al menos 10 caracteres.");return;}next.run();}).show();}
 void backupPrompt(){password("Contraseña del respaldo",()->startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/octet-stream").putExtra(Intent.EXTRA_TITLE,"colbert-cobros-"+java.time.LocalDate.now(BillingDb.ZONE)+".colbert").addCategory(Intent.CATEGORY_OPENABLE),703));}
 void restorePrompt(){password("Contraseña del respaldo",()->startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE),704));}
 @Override public void onActivityResult(int code,int result,Intent data){super.onActivityResult(code,result,data);if(code==700){authPending=false;if(result==RESULT_OK){authorized=true;background=0;open();}return;}if(result!=RESULT_OK||data==null||!authorized)return;
  if(code==702)action(()->{try(InputStream in=getContentResolver().openInputStream(data.getData())){qr=LicenseActivity.compress(in);}},this::plan);
  if(code==703){if(backupPassword==null){ui.error("Vuelve a iniciar el respaldo.");return;}action(()->{try(OutputStream out=getContentResolver().openOutputStream(data.getData(),"wt")){out.write(BillingBackup.encrypt(runtime.backup(),backupPassword));}finally{Arrays.fill(backupPassword,'\0');backupPassword=null;}},()->ui.error("Respaldo cifrado guardado. Conserva su contraseña por separado."));}
  if(code==704){if(backupPassword==null){ui.error("Vuelve a iniciar la restauración.");return;}action(()->{try(InputStream in=getContentResolver().openInputStream(data.getData())){runtime.restore(BillingBackup.decrypt(LicenseClient.read(in,150*1024*1024),backupPassword));}finally{Arrays.fill(backupPassword,'\0');backupPassword=null;}},this::home);}
  if(code==705)action(()->{try(OutputStream out=getContentResolver().openOutputStream(data.getData(),"wt")){out.write(runtime.clientConfig(exportClient).toString(2).getBytes(java.nio.charset.StandardCharsets.UTF_8));}},()->ui.error("Conexión exportada. Compártela solo con quien prepare la aplicación de este cliente."));
 }
}
